contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function performing the test
    // amount: the msg.value to send when calling play
    function run(uint amount) public {
        // ensure this contract has enough balance to send 'amount'
        require(address(this).balance >= amount, "insufficient balance");

        // read pot before
        uint potBefore = c.pot();

        // attempt the state-changing call: must be top-level
        // capture whether it succeeded by using a low-level call wrapper
        // but we are only allowed to interact through c; low-level to c.play is allowed
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        uint potAfter = c.pot();

        // If the call succeeded, potAfter must equal potBefore + amount.
        // If the call reverted, pot must be unchanged (call failed so no state change).
        // This distinguishes the original (requires equality) from the mutant (requires inequality):
        // under original, sending exactly TICKET_AMOUNT succeeds and increases pot by that amount;
        // under mutant, sending exactly TICKET_AMOUNT reverts and pot remains unchanged, violating the rule.
        assert(success ? potAfter == potBefore + amount : potAfter == potBefore);
    }

    // allow test contract to receive ETH for funding calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // In the original contract, play reverts exactly when amount == TICKET_AMOUNT.
        // We can read the constant by observing that calling with amount equal to that
        // constant reverts but different amounts do not; express as reverted == (amount == c.TICKET_AMOUNT()).
        // c.TICKET_AMOUNT is a public constant so has a getter.
        assert(reverted == (amount == c.TICKET_AMOUNT()));
    }
    receive() external payable {}
}

