pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // We'll fuzz the caller address and a nonce-like value to influence randomness inputs.
    // The deciding fuzz parameter is the amount to send; we must let the fuzzer supply it.
    function setUp() public { c = new C(); }

    // General rule: when msg.value == TICKET_AMOUNT, the reference accepts the call and updates pot accordingly;
    // the mutant that uses require(msg.value != TICKET_AMOUNT) will revert on that input, causing pot to remain unchanged.
    // We expose this by fuzzing amount and caller; if amount equals the contract's TICKET_AMOUNT the reference will
    // proceed, so we assert that after calling play() with that amount the contract's pot is NOT unchanged compared to
    // the pre-call pot in the specific way the mutant would cause.
    function testFuzz_property(uint256 amount, address caller) public {
        // Keep domains wide but sensible
        vm.assume(caller != address(0));

        uint256 ticket = 10; // matches C.TICKET_AMOUNT from source

        // We only assert the universal property for the canonical ticket amount (the change targets that equality check).
        // So drive the call with msg.value == ticket. Fuzzer still supplies 'amount' but we use it to vary caller balance setup
        // and to ensure wide wandering of state; we won't hard-code caller to any special EOA beyond fuzz.

        // fund the caller so they can send the ticket
        vm.deal(caller, 1 ether + ticket);

        uint256 potBefore = c.pot();

        // Perform the call as the fuzzed caller sending exactly the ticket amount
        vm.prank(caller);
        // Use low-level try/catch to ensure we observe whether the call reverted (mutant will revert for this input)
        bool ok;
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: in the reference contract, calling play with msg.value == TICKET_AMOUNT must NOT revert
        // (the reference uses require(msg.value == TICKET_AMOUNT)), therefore ok must be true for ALL inputs where we send the canonical ticket.
        // The mutant that changed to require(msg.value != TICKET_AMOUNT) will cause ok to be false for those inputs, so the test fails on the mutant for some inputs.
        assertTrue(ok);
    }
}

