pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an actor address and an amount to send
    function testFuzz_property(address actor, uint256 amt) public {
        // Keep amount within a wide, practical range and nonzero (admissible domain)
        vm.assume(actor != address(0));
        amt = bound(amt, 1, 1e18); // at least 1 wei, up to 1e18 to avoid absurd gas effects

        // Fund and act as the fuzzed actor
        vm.deal(actor, amt);
        uint beforePot = c.pot();

        // Perform the payable call as the actor
        vm.prank(actor);
        // record whether call succeeded; the reference should accept many values but the mutant differs
        bool ok;
        try c.play{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint afterPot = c.pot();

        // General rule: For the reference C, any successful call with nonzero value either increases pot by amt
        // (if no payout happened) or results in pot == 0 (if payout happened). So afterPot is either beforePot + amt or 0.
        // We assert that property (which the reference satisfies for all admissible inputs) — the mutant that flipped
        // the require may reject or accept different msg.value values and thus will violate this property for some inputs.
        assertTrue(ok ? (afterPot == beforePot + amt || afterPot == 0) : (afterPot == beforePot));
    }
}

