pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: an address that will call play and a uint256 seed to influence block timestamp/difficulty via vm.warp/vm.roll
    function testFuzz_property(address player, uint256 ts) public {
        // Keep player non-zero
        vm.assume(player != address(0));
        // Bound timestamp to a reasonable recent range to avoid extreme warp (but still broad)
        ts = bound(ts, 1, type(uint64).max);

        // Ensure the player has enough ETH
        uint256 ticket = 10;
        vm.deal(player, ticket);

        // Record pot before call
        uint256 before = c.pot();

        // Set block timestamp so fuzzing can explore different randomness branches
        vm.warp(uint64(ts));

        // Make the call as player paying exactly the ticket amount
        vm.prank(player);
        c.play{value: ticket}();

        // After a play where the caller paid exactly TICKET_AMOUNT, the correct contract always increases pot by that msg.value
        // unless the contract randomly awarded the pot and reset it to 0; in that winning case pot becomes 0.
        // Therefore a universal property we can assert is: either pot == 0 (a win happened) OR pot == before + ticket (no win happened).
        // This holds for the reference implementation for all admissible inputs, but the mutant that omits pot += msg.value
        // will violate this when no win occurred (pot will remain unchanged instead of increasing by ticket).

        uint256 after = c.pot();
        bool ok = (after == 0) || (after == before + ticket);
        assertTrue(ok);
    }
}

