contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz the caller address and a block timestamp to influence the pseudo-random flip
    function testFuzz_property(address fuzzCaller, uint256 fuzzTimestamp) public {
        // admissible caller must be non-zero
        vm.assume(fuzzCaller != address(0));
        // ensure caller has funds to pay ticket
        vm.deal(fuzzCaller, 100 ether);

        // Bound timestamp to reasonable range and set block.timestamp so the randomness can be influenced
        uint256 ts = bound(fuzzTimestamp, 1, type(uint64).max);
        vm.warp(ts);

        // record pot before
        uint256 before = c.pot();

        // make the call as the fuzzed caller paying exactly TICKET_AMOUNT (10)
        vm.prank(fuzzCaller);
        // play is payable and expects exactly 10 wei per spec; pay 10
        // Use low-level call to capture completion but we don't need try/catch here because play doesn't revert beyond require
        c.play{value: 10}();

        // The general rule we assert: if the play did NOT reset pot to 0, then pot increased by 10.
        // We read pot after and assert that either it was reset to 0 (a win) OR it equals before + 10 (no win and pot increased).
        uint256 after = c.pot();

        // single assertion encoding the universal property: after is either 0 (win reset) or before+10 (loss accumulates ticket)
        assertTrue(after == 0 || after == before + 10);
    }
}

